#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Wolverine@1.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using Wolverine; using Wolverine.Sagas;  // Saga状态 public class TodoSagaState {     public Guid Id { get; set; }     public int TodoId { get; set; }     public string Title { get; set; }     public SagaStatus Status { get; set; } = SagaStatus.Pending; }  public enum SagaStatus {     Pending,     Processing,     Completed,     RolledBack }  // Saga命令和事件 public record StartTodoSagaCommand(int TodoId, string Title); public record ReserveResourcesEvent(int TodoId); public record ResourcesReservedEvent(int TodoId); public record ResourcesRolledBackEvent(int TodoId);  // Saga编排 public class TodoSaga : Saga<TodoSagaState> {     public TodoSagaState State { get; set; }      public static TodoSagaState Start(StartTodoSagaCommand command)     {         return new TodoSagaState         {             Id = Guid.NewGuid(),             TodoId = command.TodoId,             Title = command.Title,             Status = SagaStatus.Pending         };     }      public async Task Handle(StartTodoSagaCommand command, IMessageBus bus)     {         State.Status = SagaStatus.Processing;         await bus.PublishAsync(new ReserveResourcesEvent(command.TodoId));     }      public async Task Handle(ResourcesReservedEvent @event, IMessageBus bus)     {         await bus.PublishAsync(new CreateTodoItemEvent(State.TodoId, State.Title));     } }
